function WaterfallGiftModel:isActValid()
    if not self:isNewGiftSystemMaintenanceOn() then return false end
    return self:isInMainTime() or self:isInAwardTime()
end

function WaterfallGiftModel:isInMainTime()
    local now = TimeKit:timeInSec()
    return (now < self.roundEndTime) and (now >= self.roundBeginTime)
end

function WaterfallGiftModel:isInAwardTime()
    local now = TimeKit:timeInSec()
    return self.rewardTimeReward == true and now < self.roundRewardEndTime
end

function WaterfallGiftModel:setRewardTimeReward()
    self:setValue("rewardTimeReward", false)
