function WaterfallGiftModel:isFinishAll()
    return self:checkNodeFinish() and self:checkProgressFinish()
end

function WaterfallGiftModel:checkNodeFinish()
    local config = self:getActConfig()
    local userData = self:getUserData()
    local fixRewardNodeList = config.fixRewardNodeList or {}
    local gotRewardNodeIndex = userData.gotRewardNodeIndex or 0
    return gotRewardNodeIndex >= #fixRewardNodeList
end

function WaterfallGiftModel:checkProgressFinish()
    local progressNodeConfig = self:getProgressNodeConfig()
    local progressNodeId = self:getProgressNodeId()
    return progressNodeId >= #progressNodeConfig
end

function WaterfallGiftModel:clearAct()
    self:setValue("roundEndTime", 0)
    self:setValue("roundBeginTime", 0)
    self:setValue("rewardTimeReward", false)
    self:setValue("roundRewardEndTime", 0)
end

