function WaterfallGiftModel:addSpecialRewardNum(idx)
    local config = self:getActConfig()
    local fixRewardNodeList = config.fixRewardNodeList or {}
    local nodeCfg = fixRewardNodeList[idx] or {}
    local specialNum = nodeCfg.specialValue2 and tonumber(nodeCfg.specialValue2) or 0
    -- printx(33, "WaterfallGiftModel:addSpecialRewardNum", idx, specialNum, tts(nodeCfg))
    if specialNum > 0 then
        local score = self:getProgressTotalScore()
        score = score + specialNum
        self:setProgressTotalScore(score)
    end
end

function WaterfallGiftModel:getSpecialRewardNumById(idx)
    local config = self:getActConfig()
    local fixRewardNodeList = config.fixRewardNodeList or {}
    local nodeCfg = fixRewardNodeList[idx] or {}
    local specialNum = nodeCfg.specialValue2 and tonumber(nodeCfg.specialValue2) or 0
    return specialNum
end

function WaterfallGiftModel:getRealFreeNum()
    local config = self:getActConfig()
    local realFreeNum = 0

    if config.fixRewardNodeList then
        for i,v in ipairs(config.fixRewardNodeList) do
            if v.freeNode then
                realFreeNum = realFreeNum + 1
            else
                break
            end
        end
    end
    return realFreeNum
end

